 double[] smooth=new double[64],peaks=new double[64];double angle,last=Stopwatch.GetTimestamp()/(double)Stopwatch.Frequency;int density;List<(double X,double Y,double Z,int Bin,double Phase)> mesh=[];List<(int A,int B)> edges=[];Bitmap? cover,background;string artKey="",backgroundPath="";bool loading;static readonly HttpClient Http=new(){Timeout=TimeSpan.FromSeconds(8)};public long Frames {get;private set;}
