 void BuildMesh(int n){density=n;mesh.Clear();edges.Clear();int m=n*2;for(int j=0;j<=n;j++)for(int i=0;i<m;i++){double lat=j/(double)n*Math.PI,lon=i/(double)m*Math.PI*2;mesh.Add((Math.Sin(lat)*Math.Cos(lon),Math.Cos(lat),Math.Sin(lat)*Math.Sin(lon),Math.Min(63,(int)((1-Math.Abs(Math.Cos(lat)))*46+i/(double)m*17)),i*2.399+j*.7));int a=j*m+i;if(j<n){edges.Add((a,a+m));edges.Add((a,(j+1)*m+(i+1)%m));}edges.Add((a,j*m+(i+1)%m));}}
 void Orb(DrawingContext c,double w,double h,double time,double low){int n=(int)settings.N("density");if(n!=density)BuildMesh(n);bool full=settings.On("fullmesh");double radius=h*settings.N("radius")/100*(1+low*settings.N("pulse")),cx=w*settings.N("sphereX")/100,cy=h*settings.N("sphereY")/100,ca=Math.Cos(angle),sa=Math.Sin(angle),ct=Math.Cos(.23),st=Math.Sin(.23);var pts=new Vector3[mesh.Count];for(int i=0;i<mesh.Count;i++){var p=mesh[i];double e=smooth[p.Bin],d=1+settings.N("deformation")*(e*(full?.22:.045)+Math.Sin(p.Phase+time*1.7)*e*(full?.16:.025));double x=(p.X*ca-p.Z*sa)*d,y=p.Y*d,z=(p.X*sa+p.Z*ca)*d;pts[i]=new((float)(cx+x*radius),(float)(cy+(y*ct-z*st)*radius),(float)(z*ct+y*st));}
