   var alpha=settings.N("opacity")*(pass==1?.85:.24);if(settings.N("glow")>0)c.DrawGeometry(null,new Pen(new SolidColorBrush(color,alpha*.08),settings.N("linewidth")+settings.N("glow")),geo);c.DrawGeometry(null,new Pen(new SolidColorBrush(color,alpha),settings.N("linewidth")),geo);
  }
  if(!full){var geo=new StreamGeometry();using(var g=geo.Open()){for(int j=0;j<14;j++){for(int i=0;i<=48;i++){double a=i/48d*Math.PI*2,r=radius*(.48+j*.007+smooth[i%48]*settings.N("deformation")*.42),t=a+Math.Sin(a*3+time*.3+j*.13)*.09;var p=new Point(cx+Math.Cos(t)*r,cy+Math.Sin(t)*r*.94);if(i==0)g.BeginFigure(p,false);else g.LineTo(p);}g.EndFigure(false);}}c.DrawGeometry(null,new Pen(new SolidColorBrush(color,settings.N("opacity")*.48),settings.N("linewidth")),geo);}
 }
 void Leds(DrawingContext c,double w,double h,double dt){double x=w*settings.N("spectrumX")/100,y=h*settings.N("spectrumY")/100,height=h*settings.N("spectrumHeight")/100,max=w*settings.N("spectrumWidth")/100,row=height/64,step=Math.Max(4,w/240),bar=Math.Max(1,row*.68);for(int i=0;i<64;i++){double len=smooth[63-i]*max;peaks[i]=Math.Max(len,peaks[i]-dt*max*.25);for(double k=0;k<len;k+=step){double f=k/Math.Max(1,len);var color=f<.4?Color.FromRgb((byte)(87+97*f/.4),(byte)(255-36*f/.4),0):f<.75?Color.FromRgb((byte)(184+71*(f-.4)/.35),(byte)(219-120*(f-.4)/.35),0):Color.FromRgb(255,(byte)(99*(1-(f-.75)/.25)),(byte)(40*(f-.75)/.25));c.FillRectangle(new SolidColorBrush(color),new Rect(x+k,y+i*row,Math.Min(settings.On("segmented")?step-1:step,len-k),bar));}if(peaks[i]>3)c.FillRectangle(new SolidColorBrush(Color.FromArgb(115,255,30,60)),new Rect(x+peaks[i],y+i*row,1,bar));}}
 void Text(DrawingContext c,string text,double x,double y,double width,double size,IBrush? color=null,bool bold=false){using(c.PushClip(new Rect(x,y,Math.Max(0,width),size*1.6))){var t=new FormattedText(text,CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Inter",FontStyle.Normal,bold?FontWeight.Bold:FontWeight.Normal),size,color??Brush("#ffffff"));c.DrawText(t,new Point(x,y));}}
